/**
 * Only the fields present change. Callers cannot change their own role or deactivate themselves,
 * and the last active superadmin cannot be demoted or deactivated. A role change or deactivation
 * revokes the target's tokens.
 */
export interface UpdateAdminRequest {
  role?: AdminRole;
  display_name?: string;
  /** `false` deactivates the account and revokes its tokens, `true` reactivates it. */
  active?: boolean;
}

export interface UpdateApiKeyRequest {
  /** Requests per minute across the fleet; `0` = unlimited. */
  rate_limit: number;
}

export interface UpdateAppRequest {
  name?: string;
  description?: string | null;
  max_channels?: number;
  /** Upper bound for `ChannelConfig.max_participants` of this app's channels. */
  max_participants_per_channel?: number;
  /**
   * Concurrent sessions (CCU) allowed fleet-wide; the next `SessionInit` beyond it fails with
   * `QUOTA_EXCEEDED`. `0` = unlimited.
   */
  max_concurrent_sessions?: number;
  /**
   * Channel participant minutes allowed per UTC calendar month; once reached, channel joins fail
   * with `QUOTA_EXCEEDED` until the month rolls over (sessions may still connect). `0` = unlimited.
   */
  monthly_participant_minutes?: number;
}

/** Only present fields are changed. */
export interface UpdateWebhookRequest {
  url?: string;
  events?: string[];
  description?: string | null;
  enabled?: boolean;
}

/**
 * One application bucket (5 minutes, or the requested `step` when rolled up). Buckets are aligned
 * to UTC epoch multiples; a bucket at or after `range.finalized_through` is still accruing.
 */
export interface UsageAppBucket {
  app_id: string;
  bucket: string;
  peak_sessions: number;
  session_minutes: number;
  sessions_started: number;
  /** Distinct users with a session in the bucket */
  unique_users: number;
  peak_participants: number;
  participant_minutes: number;
  /** Channels with at least one member during the bucket */
  active_channels: number;
  recording_seconds: number;
  /** AURX/WebRTC media bytes received from the application's players */
  media_bytes_in: number;
  /** Media bytes sent to the application's players */
  media_bytes_out: number;
  chat_messages: number;
  tts_requests: number;
  tts_characters: number;
  /** Audio milliseconds submitted to the STT provider */
  stt_audio_ms: number;
  /** Per-session quality ratings taken in the bucket */
  quality_samples: number;
  /** Sum of MOS × 1000 over the ratings (`/ quality_samples / 1000` = mean MOS) */
  mos_sum_milli: number;
  rtt_sum_ms: number;
  /** Sum of the worse direction's jitter */
  jitter_sum_ms: number;
  /** Sum of the worse direction's loss × 10 */
  loss_sum_permille: number;
  /** Ratings at 1–2 bars */
  poor_quality_samples: number;
  updated_at: string;
  /** Derived from the `quality_*` counters */
  quality: QualityAggregate;
}

/** One hourly channel bucket. */
export interface UsageChannelBucket {
  app_id: string;
  channel_id: string;
  bucket: string;
  peak_participants: number;
  participant_minutes: number;
  joins: number;
  unique_users: number;
  chat_messages: number;
  tts_requests: number;
  tts_characters: number;
  stt_audio_ms: number;
  updated_at: string;
}

/**
 * JSON form of an export. With `format=csv` the same rows are returned as `text/csv` (header row
 * first, RFC 3339 buckets) with `Content-Disposition: attachment` and `X-Aurix-Truncated: true`
 * when the row cap cut the range.
 */
export interface UsageExport {
  range: UsageExportRange;
  scope: UsageExportScope;
  count: number;
  /** More than 200 000 rows matched; narrow the range. */
  truncated: boolean;
  rows: Array<UsageAppBucket | UsageChannelBucket>;
}

export interface UsageExportRange {
  from: string;
  to: string;
}

export interface UsageRange {
  from: string;
  to: string;
  /** Resolution of `series` */
  step_secs: number;
  /**
   * Buckets before this instant are final; later ones (and the current one) are still being
   * aggregated. `null` until the first aggregation pass.
   */
  finalized_through: string | null;
}

/** Sums of additive counters and maxima of peaks over a range. */
export interface UsageTotals {
  /** Highest number of concurrently connected sessions (CCU) in any bucket */
  peak_sessions: number;
  /** Connected session time, clipped to the range */
  session_minutes: number;
  sessions_started: number;
  /** Highest number of concurrent channel memberships */
  peak_participants: number;
  /**
   * Channel membership time (a user in two channels counts twice); this is what the monthly quota
   * meters
   */
  participant_minutes: number;
  recording_seconds: number;
  /** AURX/WebRTC media bytes received from the application's players */
  media_bytes_in: number;
  /** Media bytes sent to the application's players */
  media_bytes_out: number;
  chat_messages: number;
  tts_requests: number;
  tts_characters: number;
  /** Audio milliseconds submitted to the STT provider */
  stt_audio_ms: number;
  /** Per-session quality ratings taken in the bucket */
  quality_samples: number;
  /** Sum of MOS × 1000 over the ratings (`/ quality_samples / 1000` = mean MOS) */
  mos_sum_milli: number;
  rtt_sum_ms: number;
  /** Sum of the worse direction's jitter */
  jitter_sum_ms: number;
  /** Sum of the worse direction's loss × 10 */
  loss_sum_permille: number;
  /** Ratings at 1–2 bars */
  poor_quality_samples: number;
  /** Derived from the `quality_*` counters */
  quality: QualityAggregate;
}

