/** Query parameters of `adminUsage`. */
export interface AdminUsageQuery {
  /**
   * Range start (RFC 3339), rounded down to the bucket boundary of the scope (5 minutes for
   * application rows / `step`, 1 hour for channel rows) so the bucket it falls in is included; the
   * effective value is echoed in `range.from`. Default: `to` minus 30 days. Ranges are capped at 400
   * days.
   */
  from?: string;
  /** Range end, exclusive (RFC 3339). Default: now. */
  to?: string;
}

/** Query parameters of `adminAppUsage`. */
export interface AdminAppUsageQuery {
  /**
   * Range start (RFC 3339), rounded down to the bucket boundary of the scope (5 minutes for
   * application rows / `step`, 1 hour for channel rows) so the bucket it falls in is included; the
   * effective value is echoed in `range.from`. Default: `to` minus 7 days. Ranges are capped at 400
   * days.
   */
  from?: string;
  /** Range end, exclusive (RFC 3339). Default: now. */
  to?: string;
  /**
   * Series resolution in seconds, a multiple of 300. Default: the finest of 300/3600/86400 that
   * keeps the series under 5 000 points; an explicit step producing more than 10 000 points is
   * `400`.
   */
  step?: number;
}

