/** Query parameters of `listChannelMessages`. */
export interface ListChannelMessagesQuery {
  /**
   * Only messages older than this cursor. Opaque keyset cursor (`(sent_at, id)`, URL-safe base64)
   * taken from a previous page's `next_before` / `next_after` or from a message's position; equal
   * timestamps never skip or repeat a row. Invalid cursors are `400`.
   */
  before?: string;
  /**
   * Only messages newer than this cursor (walk forward from a known position). Opaque keyset cursor
   * (`(sent_at, id)`, URL-safe base64) taken from a previous page's `next_before` / `next_after` or
   * from a message's position; equal timestamps never skip or repeat a row. Invalid cursors are
   * `400`.
   */
  after?: string;
  /** Page size; clamped to `chat.history_page_max` (default 200). */
  limit?: number;
}

/** Query parameters of `listUserMessages`. */
export interface ListUserMessagesQuery {
  /**
   * Only messages older than this cursor. Opaque keyset cursor (`(sent_at, id)`, URL-safe base64)
   * taken from a previous page's `next_before` / `next_after` or from a message's position; equal
   * timestamps never skip or repeat a row. Invalid cursors are `400`.
   */
  before?: string;
  /**
   * Only messages newer than this cursor (walk forward from a known position). Opaque keyset cursor
   * (`(sent_at, id)`, URL-safe base64) taken from a previous page's `next_before` / `next_after` or
   * from a message's position; equal timestamps never skip or repeat a row. Invalid cursors are
   * `400`.
   */
  after?: string;
  /** Page size; clamped to `chat.history_page_max` (default 200). */
  limit?: number;
  /**
   * Restrict to the conversation with this user (messages in both directions); without it every
   * directed message the user sent or received.
   */
  peer?: string;
}

